import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { ArtikalService } from '../artikal.service';
import { Artikal } from '../models/artikal';
import jwt_decode from 'jwt-decode';
import { KorisnikService } from '../korisnik.service';
import { Prodavnica } from '../models/prodavnica';

declare var google: any;

@Component({
  selector: 'app-artikal-detalji',
  templateUrl: './artikal-detalji.component.html',
  styleUrls: ['./artikal-detalji.component.css']
})
export class ArtikalDetaljiComponent implements OnInit {
  artikal: Artikal = {} as Artikal;
  prodavnica: Prodavnica = {} as Prodavnica;
  relatedArtikli: Artikal[] = [];
  prodavnicaLokacija: string = '';
  userId: string = '';
  favourites: string[] = [];

  // carousel index za detalj stranice
  carouselIndex: number = 0;

  constructor(
    private artikalService: ArtikalService,
    private route: ActivatedRoute,
    private korisnikService: KorisnikService
  ) {}

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.userId = decodedToken.id;
    }

    this.route.paramMap.subscribe((paramMap) => {
      const id = paramMap.get('id');
      if (id) {
        this.fetchArtikal(id);
      }
    });

    // (po želji) učitavanje omiljenih
    // this.korisnikService.getFavourites(this.userId).subscribe(ids => this.favourites = ids);
  }

  // Dohvatanje artikla, prodavnice i srodnih artikala
  fetchArtikal(id: string) {
    this.artikalService.getArtikalWithProdavnica(id).subscribe(
      (response: any) => {
        this.artikal = response.artikal;
        this.prodavnica = response.prodavnica;
        this.relatedArtikli = response.relatedArtikli || [];

        this.carouselIndex = 0; // reset na prvu sliku

        if (this.prodavnica?.adresa) {
          this.loadMap(this.prodavnica.adresa);
        }
      },
      (error) => {
        console.error('Greška pri dohvatanju artikla:', error);
      }
    );
  }

  // Vrati URL slike artikla (prima string ili string[])
  getArtikalImage(imagePath: string | string[] | undefined): string {
    if (!imagePath) {
      return 'assets/no-image.png'; // fallback placeholder
    }

    const path =
      Array.isArray(imagePath) && imagePath.length > 0
        ? imagePath[0]
        : (imagePath as string);

    if (!path) {
      return 'assets/no-image.png';
    }

    return `http://localhost:4000/${path}`;
  }

  // Vrati URL slike prodavnice
  getProdavnicaImage(imagePath: string | undefined): string {
    if (!imagePath) {
      return 'assets/no-shop.png'; // fallback ako nema sliku
    }
    return `http://localhost:4000/${imagePath}`;
  }

  // Google mapa
  loadMap(address: string) {
    if (!address) return;

    const geocoder = new google.maps.Geocoder();

    geocoder.geocode({ address: address }, (results: any[], status: string) => {
      if (status === 'OK' && results[0]) {
        const location = results[0].geometry.location;

        const map = new google.maps.Map(
          document.getElementById('map') as HTMLElement,
          {
            zoom: 14,
            center: location
          }
        );

        new google.maps.Marker({
          position: location,
          map: map
        });
      } else {
        console.error('Geocoding nije uspeo zbog: ' + status);
      }
    });
  }

  // Dodavanje u korpu
  addToCart(artikalId: string) {
    this.korisnikService.addToCart(this.userId, artikalId).subscribe(
      () => {
        console.log('Artikal dodat u korpu');
        this.korisnikService.getCartCount(this.userId).subscribe();
      },
      (error) => {
        console.error('Greška pri dodavanju u korpu:', error);
      }
    );
  }

  // Omiljeni
  toggleFavourite(artikalId: string) {
    if (this.favourites.includes(artikalId)) {
      this.korisnikService.removeFromFavourites(this.userId, artikalId).subscribe(
        () => {
          this.favourites = this.favourites.filter((id) => id !== artikalId);
        }
      );
    } else {
      this.korisnikService.addToFavourites(this.userId, artikalId).subscribe(
        () => {
          this.favourites.push(artikalId);
        }
      );
    }
  }

  isFavourite(artikalId: string): boolean {
    return this.favourites.includes(artikalId);
  }

  // === CAROUSEL FUNKCIJE ZA DETALJ STRANICU ===

  nextCarouselImage() {
    if (!this.artikal.slike || this.artikal.slike.length === 0) return;
    this.carouselIndex =
      (this.carouselIndex + 1) % this.artikal.slike.length;
  }

  prevCarouselImage() {
    if (!this.artikal.slike || this.artikal.slike.length === 0) return;
    this.carouselIndex =
      (this.carouselIndex - 1 + this.artikal.slike.length) %
      this.artikal.slike.length;
  }

  goToCarouselImage(index: number) {
    if (!this.artikal.slike || this.artikal.slike.length === 0) return;
    this.carouselIndex = index;
  }
}
<div class="artikal-details-page">
  <!-- Gornji deo stranice -->
  <div class="upper-section">
    <div class="artikal-info">
      <!-- Leva strana - glavni artikal (carousel) -->
      <div class="artikal-card-glavni">
        <div
          class="detalji-carousel-wrapper"
          *ngIf="artikal.slike && artikal.slike.length > 0"
        >
          <!-- Trenutna slika iz niza -->
          <img
            [src]="getArtikalImage(artikal.slike[carouselIndex])"
            alt="Artikal slika"
            class="detalji-carousel-image"
          />

          <!-- Strelice -->
          <button
            class="detalji-carousel-arrow left"
            type="button"
            (click)="prevCarouselImage()"
          >
            ‹
          </button>
          <button
            class="detalji-carousel-arrow right"
            type="button"
            (click)="nextCarouselImage()"
          >
            ›
          </button>

          <!-- Tačkice -->
          <div class="detalji-carousel-dots">
            <span
              *ngFor="let slika of artikal.slike; let i = index"
              class="dot"
              [class.active]="i === carouselIndex"
              (click)="goToCarouselImage(i)"
            ></span>
          </div>
        </div>

        <!-- Fallback ako nema sliku -->
        <div
          class="detalji-carousel-wrapper"
          *ngIf="!artikal.slike || artikal.slike.length === 0"
        >
          <img
            [src]="getArtikalImage(undefined)"
            alt="Artikal slika"
            class="detalji-carousel-image"
          />
        </div>
      </div>

      <!-- Desno od slike - opis artikla -->
      <div class="artikal-description">
        <h2>{{ artikal.tip }}</h2>
        <p><strong>Veličina:</strong> {{ artikal.velicina }}</p>
        <p><strong>Cena:</strong> {{ artikal.cena }} din</p>

        <button
          class="add-to-cart-btn"
          (click)="addToCart(artikal._id); $event.stopPropagation()"
        >
          Dodaj u korpu
        </button>
        <br /><br />

        <!-- Ovde možeš prebaciti na toggleFavourite -->
        <button
          class="add-to-cart-btn"
          (click)="toggleFavourite(artikal._id); $event.stopPropagation()"
        >
          {{ isFavourite(artikal._id) ? 'Ukloni iz omiljenih' : 'Dodaj u omiljene' }}
        </button>
      </div>
    </div>

    <!-- Desna strana - prodavnica + mapa -->
    <div class="artikal-location">
      <div class="prodavac-info">
        <h3>
          Iz prodavnice
          <a
            [routerLink]="['/prodavac', prodavnica._id]"
            class="prodavac-link"
          >
            {{ prodavnica.ime }}
          </a>
        </h3>
        <img
          [src]="getProdavnicaImage(prodavnica.slika)"
          alt="Slika prodavnice"
          class="prodavnica-image"
        />
      </div>

      <h3>Lokacija proizvoda</h3>
      <div id="map" class="google-map"></div>
    </div>
  </div>

  <!-- Donji deo stranice - ostali proizvodi iz prodavnice -->
  <div class="related-products">
    <h3>Pogledajte ostale proizvode iz prodavnice {{ prodavnica.ime }}</h3>

    <div class="artikli-container-wrapper">
      <div class="artikli-container" #artikliContainer>
        <div
          class="artikal-card"
          *ngFor="let relatedArtikal of relatedArtikli"
          [routerLink]="['/artikal', relatedArtikal._id]"
        >
          <img
            [src]="getArtikalImage(relatedArtikal.slike)"
            alt="Artikal slika"
            class="artikal-image"
          />
          <div class="artikal-info">
            <p>{{ relatedArtikal.cena }} din</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
